'use strict';
const SCHEMA = {
  Students:['id','name','email','aliases','status','created_at','notes'],
  Courses:['id','student_id','title','cycle_no','start_date','purchased_minutes','status','previous_course_id','created_at','closed_at'],
  Groups:['id','name','member_ids','created_at'],
  Schedules:['id','date','student_id','group_id','start_time','end_time','tutor','repeat_rule','status','notes','created_at'],
  Sessions:['id','date','start_time','end_time','mode','group_id','tutor','time_source','status','source_file','notes','created_at'],
  Attendance:['id','session_id','student_id','course_id','join_time','leave_time','actual_minutes','deduct_minutes','status','source_name','created_at'],
  Ledger:['id','student_id','course_id','session_id','type','minutes','note','created_at'],
  Imports:['id','fingerprint','filename','date','session_id','created_at'],
  Audit:['id','action','target_id','details','created_at']
};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>{const m=Math.max(0,Math.round(Number(n)||0));return `${Math.floor(m/60)}:${String(m%60).padStart(2,'0')}`;};
const nice=n=>{const m=Math.round(Number(n)||0);return `${Math.floor(Math.abs(m)/60)} ชม. ${Math.abs(m)%60} นาที`;};
const num=n=>Math.round(Number(n)||0);
const uuid=()=>((typeof crypto!=='undefined'&&crypto.randomUUID)?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const dateNow=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Bangkok'});
const now=()=>new Date().toISOString();
const inputVal=(form,name)=>String(new FormData(form).get(name)||'').trim();
function minutesOf(s){const m=String(s||'').match(/^(\d{1,2}):(\d\d)(?::\d\d)?$/);if(!m)return NaN;const h=+m[1],mm=+m[2];return h<24&&mm<60?h*60+mm:NaN;}
function duration(start,end){const a=minutesOf(start),b=minutesOf(end);if(!Number.isFinite(a)||!Number.isFinite(b))return NaN;let d=b-a;if(d<0)d+=1440;return d;}
const row=(name,obj)=>SCHEMA[name].map(k=>obj[k]??'');
const obj=(name,values)=>Object.fromEntries(SCHEMA[name].map((k,i)=>[k,values[i]??'']));
const norm=s=>String(s||'').toLowerCase().normalize('NFKC').replace(/\s+/g,' ').trim();
function dateValid(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(new Date(s+'T00:00:00').getTime());}
const all=(sheet)=>state.data[sheet]||[];
const byId=(sheet,id)=>all(sheet).find(x=>x.id===id);
const coursesOf=id=>all('Courses').filter(c=>c.student_id===id).sort((a,b)=>num(b.cycle_no)-num(a.cycle_no));
const liveCourses=id=>coursesOf(id).filter(c=>c.status==='active'||c.status==='held');
const studentName=id=>byId('Students',id)?.name||'ไม่พบนักเรียน';
const courseTitle=id=>{const c=byId('Courses',id);return c?`${c.title} · รอบ ${c.cycle_no}`:'ไม่พบคอร์ส';};
const balance=id=>all('Ledger').filter(l=>l.course_id===id).reduce((s,l)=>s+num(l.minutes),0);
const currentStudentTotal=id=>liveCourses(id).reduce((s,c)=>s+balance(c.id),0);
const pill=(txt,tone='')=>`<span class="badge ${tone}">${esc(txt)}</span>`;
const options=(arr,selected='',placeholder='เลือก...',val='id',label='name')=>`<option value="">${esc(placeholder)}</option>`+arr.map(it=>`<option value="${esc(it[val])}" ${String(it[val])===String(selected)?'selected':''}>${esc(it[label])}</option>`).join('');
const studentOptions=(selected='')=>options(all('Students').filter(x=>x.status!=='archived').sort((a,b)=>a.name.localeCompare(b.name,'th')),selected,'— เลือกนักเรียน —');
const courseOptions=(studentId,selected='')=>options(liveCourses(studentId).map(c=>({id:c.id,name:`${c.title} · รอบ ${c.cycle_no} · คงเหลือ ${fmt(balance(c.id))}`})),selected,'— เลือกคอร์ส —');
function toast(msg,error=false){const el=$('#toast-root');el.innerHTML=`<div class="toast ${error?'error':''}">${esc(msg)}</div>`;setTimeout(()=>{if(el)el.innerHTML=''},4300);}
function modal(title,body,footer='',wide=false){$('#modal-root').innerHTML=`<div class="overlay" id="overlay"><div class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-top"><h2 class="modal-title">${esc(title)}</h2><button class="xbtn" data-close>×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</div></div>`;}
function closeModal(){$('#modal-root').innerHTML='';}
function notice(e){toast(e?.message||String(e),true);console.error(e);}
const head=(ey,title,desc,action='')=>`<div class="page-header"><div><div class="eyebrow">${ey}</div><h1>${title}</h1><p class="subtle">${desc}</p></div>${action}</div>`;
const field=(name,label,type='text',value='',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const selectField=(name,label,opts,extra='')=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${opts}</select></div>`;
const btn=(label,action,extra='')=>`<button type="button" class="btn ${extra}" data-action="${action}">${label}</button>`;
let store=null;
const config=window.TUTOR_CONFIG||{};
const liveConfigured=!!(config.googleClientId&&config.spreadsheetId);
const state={view:'dashboard',data:{},mode:liveConfigured?'needs_login':'demo',token:'',tokenClient:null,studentId:'',showArchive:false,importQueue:[],importIndex:0,importDraft:null,search:'',filter:'all',busy:false};
function makeDemo(){
  const empty=Object.fromEntries(Object.keys(SCHEMA).map(k=>[k,[]]));
  const t=now(),ds=dateNow();
  const s1={id:'demo-student-a',name:'น้อง A',email:'',aliases:'A Biology, iPad A',status:'active',created_at:t,notes:'ตัวอย่างนักเรียน'};
  const s2={id:'demo-student-b',name:'น้อง B',email:'',aliases:'',status:'active',created_at:t,notes:''};
  const c1={id:'demo-course-a',student_id:s1.id,title:'Biology Olympiad',cycle_no:2,start_date:ds,purchased_minutes:600,status:'active',previous_course_id:'demo-course-old',created_at:t,closed_at:''};
  const cold={id:'demo-course-old',student_id:s1.id,title:'Biology Olympiad',cycle_no:1,start_date:'2026-09-01',purchased_minutes:600,status:'archived',previous_course_id:'',created_at:t,closed_at:t};
  const c2={id:'demo-course-b',student_id:s2.id,title:'A-Level Biology',cycle_no:1,start_date:ds,purchased_minutes:720,status:'active',previous_course_id:'',created_at:t,closed_at:''};
  empty.Students=[s1,s2];empty.Courses=[c1,cold,c2];
  empty.Ledger=[
    {id:uuid(),student_id:s1.id,course_id:cold.id,session_id:'',type:'purchase',minutes:600,note:'ซื้อรอบแรก',created_at:t},
    {id:uuid(),student_id:s1.id,course_id:cold.id,session_id:'',type:'deduct',minutes:-600,note:'ตัวอย่างประวัติเก่า',created_at:t},
    {id:uuid(),student_id:s1.id,course_id:c1.id,session_id:'',type:'purchase',minutes:600,note:'ต่อคอร์สใหม่',created_at:t},
    {id:uuid(),student_id:s1.id,course_id:c1.id,session_id:'demo-session',type:'deduct',minutes:-120,note:'คาบตัวอย่าง',created_at:t},
    {id:uuid(),student_id:s2.id,course_id:c2.id,session_id:'',type:'purchase',minutes:720,note:'ลงทะเบียน',created_at:t}
  ];
  empty.Sessions=[{id:'demo-session',date:ds,start_time:'18:00',end_time:'20:00',mode:'manual',group_id:'',tutor:'Tutor',time_source:'tutor',status:'approved',source_file:'',notes:'คาบตัวอย่าง',created_at:t}];
  empty.Attendance=[{id:uuid(),session_id:'demo-session',student_id:s1.id,course_id:c1.id,join_time:'18:00',leave_time:'20:00',actual_minutes:120,deduct_minutes:120,status:'approved',source_name:'',created_at:t}];
  return empty;
}
class DemoStore{
  async load(){let raw=localStorage.getItem('awtutor_v1_demo');if(!raw){const demo=makeDemo();localStorage.setItem('awtutor_v1_demo',JSON.stringify(demo));return demo;}try{return JSON.parse(raw);}catch{return makeDemo();}}
  async commit(changes){const d=await this.load();Object.entries(changes.update||{}).forEach(([k,rows])=>rows.forEach(change=>{const i=d[k].findIndex(x=>x.id===change.id);if(i<0)throw Error('Row not found');d[k][i]=change;}));Object.entries(changes.add||{}).forEach(([k,rows])=>d[k].push(...rows));localStorage.setItem('awtutor_v1_demo',JSON.stringify(d));return d;}
}
class SheetsStore{
  constructor(token){this.token=token;this.sids={};}
  async request(path,method='GET',payload){const res=await fetch('https://sheets.googleapis.com/v4/spreadsheets/'+encodeURIComponent(config.spreadsheetId)+path,{method,headers:{Authorization:'Bearer '+this.token,...(payload?{'Content-Type':'application/json'}:{})},body:payload?JSON.stringify(payload):undefined});if(!res.ok){const err=await res.json().catch(()=>({}));let reason=err.error?.message||`HTTP ${res.status}`;if(res.status===401)reason+=' · หมดอายุการเชื่อมต่อ กรุณา Sign in อีกครั้ง';throw Error(reason);}return res.json();}
  async load(){const meta=await this.request('?fields=sheets(properties(sheetId,title))');this.sids=Object.fromEntries(meta.sheets.map(s=>[s.properties.title,s.properties.sheetId]));for(const name of Object.keys(SCHEMA))if(this.sids[name]===undefined)throw Error('ไม่พบชีต '+name+' — กรุณารัน setupTutorOS() ก่อน');const ranges=Object.keys(SCHEMA).map(s=>`${s}!A2:${String.fromCharCode(64+SCHEMA[s].length)}10000`);const data=await this.request('/values:batchGet?ranges='+ranges.map(encodeURIComponent).join('&ranges=')+'&valueRenderOption=UNFORMATTED_VALUE');return Object.fromEntries(Object.keys(SCHEMA).map((s,i)=>[s,(data.valueRanges[i]?.values||[]).filter(row=>row.some(v=>v!==''&&v!==null)).map(r=>obj(s,r))]));}
  async commit(changes){const requests=[];const latest=state.data;for(const [sheet,updates] of Object.entries(changes.update||{})){const ids=latest[sheet].map(x=>x.id);for(const value of updates){const i=ids.indexOf(value.id);if(i<0)throw Error(`Row ${value.id} not found`);requests.push({updateCells:{range:{sheetId:this.sids[sheet],startRowIndex:i+1,endRowIndex:i+2,startColumnIndex:0,endColumnIndex:SCHEMA[sheet].length},rows:[{values:row(sheet,value).map(toCell)}],fields:'userEnteredValue'}});}}for(const [sheet,adds] of Object.entries(changes.add||{})){if(!adds.length)continue;requests.push({appendCells:{sheetId:this.sids[sheet],rows:adds.map(a=>({values:row(sheet,a).map(toCell)})),fields:'userEnteredValue'}});}if(!requests.length)return state.data;await this.request(':batchUpdate','POST',{requests});return this.load();}
}
function toCell(value){if(typeof value==='number')return {userEnteredValue:{numberValue:value}};return {userEnteredValue:{stringValue:String(value??'')}};}
async function reload(){state.data=await store.load();render();}
async function commit(changes){if(state.busy)throw Error('กำลังบันทึกข้อมูล');state.busy=true;try{state.data=await store.commit(changes);render();}finally{state.busy=false;}}
function saveAudit(action,target,details){return {id:uuid(),action,target_id:target,details:JSON.stringify(details||{}),created_at:now()};}
function init(){store=new DemoStore();const back=document.createElement('div');back.className='mobile-backdrop';back.id='mobile-backdrop';document.body.appendChild(back);document.addEventListener('click',onClick);document.addEventListener('submit',onSubmit);document.addEventListener('change',onChange);document.addEventListener('input',onInput);$('#menu-toggle').onclick=()=>toggleMenu(true);back.onclick=()=>toggleMenu(false);$('#refresh-btn').onclick=()=>reload().then(()=>toast('อัปเดตข้อมูลแล้ว')).catch(notice);$('#connect-side').onclick=openConnection;$('#account-btn').onclick=openConnection;reload().catch(notice);}
function toggleMenu(show){$('#sidebar').classList.toggle('open',show);$('#mobile-backdrop').classList.toggle('open',show);}
function render(){const v=state.view;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===v));$('#crumb').textContent=v.toUpperCase();$('#mode-pill').textContent=state.mode==='live'?'GOOGLE SHEETS':state.mode==='needs_login'?'CONNECT GOOGLE':'DEMO DATA';$('#side-mode').textContent=state.mode==='live'?'LIVE DATABASE':'DEMO MODE';$('#account-btn').textContent=state.mode==='live'?'G':'S';const views={dashboard,students,groups,schedule,manual,import:importPage,reviews,reports};$('#app').innerHTML=(views[v]||dashboard)();}
function go(view){state.view=view;toggleMenu(false);render();window.scrollTo(0,0);}
const activeStudents=()=>all('Students').filter(s=>s.status==='active');
const sessionsSorted=()=>[...all('Sessions')].sort((a,b)=>(b.date+' '+b.start_time).localeCompare(a.date+' '+a.start_time));
function dashboard(){const active=activeStudents(),pending=all('Sessions').filter(s=>s.status==='pending'),approved=all('Sessions').filter(s=>s.status==='approved');const rem=active.reduce((n,s)=>n+currentStudentTotal(s.id),0);const usedThisMonth=approved.filter(s=>s.date?.slice(0,7)===dateNow().slice(0,7)).reduce((n,s)=>n+duration(s.start_time,s.end_time),0);return `${head('OVERVIEW / LEARNING HOURS','Tutor Dashboard','บริหารชั่วโมงเรียน นักเรียน และคาบเรียนจากที่เดียว',`<div class="button-row">${btn('＋ เพิ่มนักเรียน','add-student','soft')}${btn('＋ บันทึกเวลาเรียน','go-manual','primary')}</div>`)}
<div class="stats"><div class="stat"><div class="mini">Active Students</div><div class="big">${active.length}</div><div class="foot">นักเรียนที่กำลังเรียน</div></div><div class="stat"><div class="mini">Remaining Hours</div><div class="big">${fmt(rem)}</div><div class="foot">รวมยอดของคอร์สที่ใช้งาน</div></div><div class="stat"><div class="mini">Pending Reviews</div><div class="big">${pending.length}</div><div class="foot">รออนุมัติก่อนตัดชั่วโมง</div></div><div class="stat"><div class="mini">Teaching This Month</div><div class="big">${fmt(usedThisMonth)}</div><div class="foot">รวมระยะเวลาคาบเรียนที่อนุมัติ</div></div></div>
<div class="two-col"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Recent Sessions</h2><p class="panel-desc">รายการล่าสุดและสถานะอนุมัติ</p></div>${btn('View all →','go-reviews','small')}</div>${sessionsSorted().slice(0,5).map(s=>`<div class="list-row"><div class="person"><div class="avatar">◷</div><div><strong>${esc(s.date)} · ${esc(s.start_time)}–${esc(s.end_time)}</strong><small>${esc(s.mode==='excel'?'Excel Import':'Manual Entry')} · ${all('Attendance').filter(a=>a.session_id===s.id).length} คน</small></div></div><div>${pill(s.status,s.status==='approved'?'green':s.status==='pending'?'gold':'')}</div></div>`).join('')||'<div class="empty">ยังไม่มีคาบเรียน</div>'}</section>
<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Low Hour Balances</h2><p class="panel-desc">คอร์สที่เหลือไม่เกิน 2 ชั่วโมง</p></div></div>${all('Courses').filter(c=>c.status==='active'&&balance(c.id)<=120).slice(0,6).map(c=>`<div class="list-row"><div><strong style="font-size:12px">${esc(studentName(c.student_id))}</strong><div class="td-secondary">${esc(c.title)}</div></div><strong class="${balance(c.id)<=0?'error-text':'amount'}">${fmt(balance(c.id))}</strong></div>`).join('')||'<div class="empty">ยังไม่มีคอร์สใกล้หมด</div>'}</section></div>
<div class="panel"><div class="panel-head"><div><h2 class="panel-title">Quick Actions</h2><p class="panel-desc">เริ่มงานที่ใช้งานบ่อย</p></div></div><div class="button-row">${btn('⇧ Upload Meet Excel','go-import','soft')}${btn('☑ Approve Attendance','go-reviews')}${btn('♙ Manage Students','go-students')}${btn('⚙ Connect Google Sheets','connection')}</div></div>${state.mode!=='live'?'<div class="note warn">ขณะนี้เป็นข้อมูลตัวอย่างในเบราว์เซอร์ ยังไม่เชื่อม Google Sheets — ไปที่ Connection settings เพื่อตั้งค่าใช้งานจริง</div>':''}`;}
function students(){const ss=all('Students').filter(s=>norm(s.name+' '+s.email+' '+s.aliases).includes(norm(state.search)));return `${head('PEOPLE / ENROLLMENT','Students & Courses','โปรไฟล์นักเรียน แพ็กเกจชั่วโมง และประวัติการต่อคอร์ส',`<div class="button-row">${btn('＋ สร้างคอร์ส','add-course','soft')}${btn('＋ เพิ่มนักเรียน','add-student','primary')}</div>`)}<div class="panel"><div class="toolbar"><input class="search" id="student-search" placeholder="ค้นหาชื่อ ชื่อเล่น หรืออีเมล" value="${esc(state.search)}"><span class="muted compact">${ss.length} students</span></div><div class="table-wrap"><table><thead><tr><th>STUDENT</th><th>ACTIVE COURSES</th><th>HOURS REMAINING</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${ss.map(s=>`<tr><td><button class="link-btn" data-action="student-detail" data-id="${esc(s.id)}">${esc(s.name)}</button><div class="td-secondary">${esc(s.email||s.id.slice(0,12))}</div></td><td>${liveCourses(s.id).length} courses</td><td><strong class="amount">${fmt(currentStudentTotal(s.id))}</strong></td><td>${pill(s.status,s.status==='active'?'green':'')}</td><td><div class="button-row">${btnInline('ดูโปรไฟล์','student-detail',s.id)} ${btnInline('ต่อคอร์ส','renew-student',s.id)}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">ยังไม่มีนักเรียนตรงกับคำค้น</td></tr>'}</tbody></table></div></div>${state.studentId?studentDetail(state.studentId):''}`;}
const btnInline=(label,action,id)=>`<button class="btn small" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
function studentDetail(id){const s=byId('Students',id);if(!s)return '';const cs=coursesOf(id);const shown=state.showArchive?cs:cs.filter(c=>c.status==='active');const history=all('Attendance').filter(a=>a.student_id===id).sort((a,b)=>(byId('Sessions',b.session_id)?.date||'').localeCompare(byId('Sessions',a.session_id)?.date||''));return `<section class="panel" id="profile"><div class="panel-head"><div><h2 class="panel-title">${esc(s.name)} · Student Profile</h2><p class="panel-desc">${esc(s.notes||'Course wallet & learning history')}</p></div><div class="button-row">${btnInline('แก้ไขนักเรียน','edit-student',id)} ${btnInline('＋ คอร์สใหม่','new-course-for',id)} <button class="btn small" data-action="hide-student">ปิด</button></div></div><div class="metric-strip"><div><small>Active courses</small><b>${liveCourses(id).length}</b></div><div><small>Available balance</small><b>${fmt(currentStudentTotal(id))}</b></div><div><small>Past course cycles</small><b>${cs.filter(c=>c.status==='archived').length}</b></div></div><div class="panel-head mt20"><h3 class="panel-title">Course Cycles</h3><button class="link-btn" data-action="toggle-archive">${state.showArchive?'ซ่อนประวัติเก่า':'ดูประวัติคอร์สเก่า →'}</button></div><div class="cards-grid">${shown.map(c=>`<div class="sheet-card"><div class="flex-between"><strong>${esc(c.title)}</strong>${pill(c.status,c.status==='active'?'green':'')}</div><p class="mini">รอบที่ ${esc(c.cycle_no)} · เริ่ม ${esc(c.start_date)}</p><div class="big">${fmt(balance(c.id))}</div><div class="mini">ชั่วโมงคงเหลือ · ลงทะเบียน ${fmt(c.purchased_minutes)} ชั่วโมง</div><div class="button-row mt12">${c.status==='active'?`${btnInline('ต่อคอร์ส','renew-course',c.id)} ${btnInline('เติมชั่วโมง','topup-course',c.id)} ${btnInline('ปรับยอด','adjust-course',c.id)}`:''}${btnInline('รายละเอียด','course-history',c.id)}</div></div>`).join('')||'<div class="empty">ยังไม่มีคอร์สที่แสดง</div>'}</div><div class="panel-head mt20"><h3 class="panel-title">Recent Attendance</h3></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>COURSE</th><th>ACTUAL</th><th>DEDUCTED</th><th>STATUS</th></tr></thead><tbody>${history.slice(0,12).map(a=>`<tr><td>${esc(byId('Sessions',a.session_id)?.date||'-')}</td><td>${esc(courseTitle(a.course_id))}</td><td>${fmt(a.actual_minutes)}</td><td>${fmt(a.deduct_minutes)}</td><td>${pill(a.status,a.status==='approved'?'green':'gold')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">ไม่มีประวัติการเรียน</td></tr>'}</tbody></table></div></section>`;}
function groups(){return `${head('GROUP LEARNING / MEMBERS','Class Groups','จัดกลุ่มเรียนและเลือกนักเรียนที่จะถูกตัดชั่วโมงตามแต่ละคาบ',btn('＋ สร้างกลุ่มเรียน','add-group','primary'))}<div class="cards-grid">${all('Groups').map(g=>{const ids=(g.member_ids||'').split('|').filter(Boolean);return `<div class="sheet-card"><div class="flex-between"><strong>${esc(g.name)}</strong>${pill(ids.length+' students','green')}</div><div class="mini" style="line-height:1.8">${ids.map(studentName).map(esc).join(' · ')||'ยังไม่มีสมาชิก'}</div><div class="button-row mt20">${btnInline('แก้ไขกลุ่ม','edit-group',g.id)} ${btnInline('ลงเวลาเรียน','record-group',g.id)}</div></div>`}).join('')||'<div class="empty">ยังไม่มีกลุ่มเรียน เพิ่มกลุ่มเพื่อเริ่มต้น</div>'}</div>`;}
function manual(){const g=all('Groups');return `${head('ATTENDANCE / MANUAL','Record Hours','บันทึกเวลาเริ่ม–สิ้นสุด เลือกสมาชิกและคอร์ส ก่อนส่งรายการตรวจสอบ',btn('⇧ Import Excel','go-import','soft'))}<div class="panel"><form id="manual-form" class="form"><div class="grid-3">${field('class_date','วันที่เรียน','date',dateNow(),'required')}${field('class_start','เวลาเริ่ม','time','18:00','required')}${field('class_end','เวลาสิ้นสุด','time','20:00','required')}</div><div class="grid-2">${selectField('group_id','กลุ่มเรียน (ไม่บังคับ)',`<option value="">รายบุคคล / เลือกเอง</option>${g.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}`)}${field('tutor','ชื่อติวเตอร์','text','Suthawarin','required')}</div><div class="grid-2">${selectField('deduction_mode','วิธีตัดชั่วโมง',`<option value="full">ใช้เวลาติวเตอร์ / เวลาที่กรอก</option><option value="custom">กำหนดนาทีที่จะตัดเอง</option>`)}${field('class_custom','ตัดชั่วโมง (นาที เมื่อเลือก Custom)','number','120','min="0" max="1440"')}</div><div class="field"><label>เลือกผู้เข้าร่วมและคอร์สที่จะตัด</label><div class="note">นักเรียนที่ไม่ถูกติ๊กจะไม่ถูกลง Attendance และไม่ถูกตัดชั่วโมง</div></div><div id="manual-students">${manualStudents()}</div><div class="field"><label>หมายเหตุ</label><textarea name="class_notes" rows="2" placeholder="หัวข้อที่เรียน / บันทึกเพิ่มเติม"></textarea></div><div class="button-row"><button class="btn primary" type="submit">บันทึกรอตรวจสอบ →</button><span class="helper">ยังไม่ตัดชั่วโมงจนกว่าจะกด Approve ในหน้า Review</span></div></form></div>`;}
function manualStudents(groupId=''){const group=byId('Groups',groupId),members=(group?.member_ids||'').split('|').filter(Boolean);return `<div class="table-wrap"><table><thead><tr><th>SELECT</th><th>STUDENT</th><th>COURSE TO DEDUCT</th><th>AVAILABLE</th><th>OVERRIDE (MIN)</th></tr></thead><tbody>${all('Students').filter(s=>s.status==='active').map(s=>{const cs=liveCourses(s.id);return `<tr><td><input type="checkbox" name="participant" class="manual-check" value="${esc(s.id)}" ${members.includes(s.id)?'checked':''} ${cs.length?'':'disabled'}></td><td>${esc(s.name)}</td><td><select class="manual-course" data-student="${esc(s.id)}" style="width:100%;border:1px solid #e3e9e2;border-radius:7px;padding:8px">${courseOptions(s.id,cs[0]?.id)}</select></td><td>${fmt(currentStudentTotal(s.id))}</td><td><input type="number" class="manual-minute" data-student="${esc(s.id)}" min="0" max="720" step="1" placeholder="auto" style="width:83px;border:1px solid #e3e9e2;border-radius:7px;padding:8px"></td></tr>`}).join('')||'<tr><td colspan="4" class="empty">ยังไม่มีนักเรียนหรือคอร์ส</td></tr>'}</tbody></table></div>`;}
function importPage(){const draft=state.importDraft;return `${head('AUTOMATION / ATTENDANCE','Import Google Meet Excel','นำเข้ารายงานการเข้าร่วม เลือกเวลาติวเตอร์หรือเวลานักเรียนและตรวจสอบก่อนบันทึก',btn('＋ Manual Entry','go-manual','soft'))}<section class="panel"><div class="dropzone"><div style="font-size:34px;color:#28704f">▤</div><strong>Upload Meet attendance report</strong><small>รองรับ XLSX / XLS หลายไฟล์ · รายงานภาษาไทยตามตัวอย่างที่ให้มา</small><label class="btn primary" for="excel-file">เลือกไฟล์ Excel</label><input id="excel-file" type="file" accept=".xlsx,.xls,.csv" multiple hidden></div><div class="note mt12">ระบบอ่านคอลัมน์ ชื่อ · นามสกุล · อีเมล · ระยะเวลา · เวลาที่เข้าร่วม · เวลาที่ออก และตรวจจับวันที่จากชื่อไฟล์ ตัวเลือกเวลาเข้า–ออกเดิมจะยังเก็บอยู่แม้เลือกหักชั่วโมงด้วยวิธีอื่น</div></section>${draft?importReview(draft):''}`;}
function importReview(d){return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Review Imported Report</h2><p class="panel-desc">${esc(d.filename)} · ${d.people.length} participant identities</p></div>${state.importQueue.length>1?pill(`ไฟล์ ${state.importIndex+1}/${state.importQueue.length}`,'blue'):''}</div><div class="grid-3">${field('import-date','วันที่เรียน','date',d.date,'required')}${selectField('import-tutor','ผู้ที่เป็นติวเตอร์',d.people.map((p,i)=>`<option value="${i}" ${i===d.tutorIndex?'selected':''}>${esc(p.name)} (${fmt(p.actual)})</option>`).join(''))}${selectField('import-group','กลุ่มเรียน (ถ้ามี)',`<option value="">รายบุคคล</option>${all('Groups').map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}`)}</div><div class="grid-2 mt12">${selectField('import-basis','ค่าเริ่มต้นในการตัดชั่วโมง',`<option value="tutor" ${d.basis==='tutor'?'selected':''}>ยึดเวลาติวเตอร์</option><option value="student" ${d.basis==='student'?'selected':''}>ยึดเวลานักเรียนรายคน</option><option value="overlap" ${d.basis==='overlap'?'selected':''}>เวลาที่อยู่พร้อมกับติวเตอร์</option><option value="person" ${d.basis==='person'?'selected':''}>เลือกผู้เข้าร่วมหนึ่งคนเป็นเกณฑ์</option><option value="custom" ${d.basis==='custom'?'selected':''}>กำหนดเอง (Custom)</option>`)}${selectField('import-source','บุคคลที่ใช้เป็นเกณฑ์ (สำหรับ Choose participant)',d.people.map((p,i)=>`<option value="${i}" ${i===d.sourceIndex?'selected':''}>${esc(p.name)}</option>`).join(''))}</div><div class="divider"></div><div class="note">การจับคู่ชื่ออัตโนมัติเป็นเพียงข้อเสนอจากชื่อเล่น / อีเมล กรุณาตรวจสอบทุกคนก่อนกดยืนยัน ห้ามบันทึกบุคคลที่ยังไม่สามารถระบุตัวได้</div><div id="import-participants">${importParticipants(d)}</div><div class="button-row mt20"><button class="btn primary" data-action="save-import">บันทึกทั้งหมดเป็น Pending Review →</button><button class="btn" data-action="skip-import">${state.importQueue.length>1?'ข้ามไปไฟล์ถัดไป':'ยกเลิก Preview'}</button></div></section>`;}
function importParticipants(d){return d.people.map((p,i)=>{const isTutor=i===d.tutorIndex;const student=p.studentId?byId('Students',p.studentId):null;const course=student?liveCourses(student.id)[0]:null;const calc=calculatedImport(d,p);return `<div class="review-row" data-person="${i}"><div class="flex-between"><label class="check"><input type="checkbox" data-import-include="${i}" ${p.include&&!isTutor?'checked':''} ${isTutor?'disabled':''}><span>${esc(p.name)}</span></label>${isTutor?pill('TUTOR','blue'):pill('ACTUAL '+fmt(p.actual))}</div><div class="helper">Join ${esc(p.join||'—')} · Leave ${esc(p.leave||'—')} · ${p.segments.length} segment(s) · ${esc(p.email||'ไม่ระบุอีเมล')}</div>${!isTutor?`<div class="grid-3"><div class="field"><label>จับคู่นักเรียน</label><select data-import-student="${i}">${studentOptions(p.studentId)}</select></div><div class="field"><label>คอร์สที่ใช้ตัด</label><select data-import-course="${i}">${courseOptions(p.studentId,p.courseId||course?.id)}</select></div><div class="field"><label>หักชั่วโมง (นาที)</label><input type="number" data-import-minutes="${i}" min="0" max="1440" value="${num(p.manualMinutes??calc)}"></div></div>`:''}</div>`}).join('');}
function calculatedImport(d,p){const tutor=d.people[d.tutorIndex];if(d.basis==='custom')return num(p.manualMinutes??p.actual);if(d.basis==='student')return p.actual;if(d.basis==='overlap')return tutor?overlapMinutes(tutor.segments,p.segments):p.actual;if(d.basis==='person')return d.people[d.sourceIndex]?.actual??p.actual;return tutor?.actual??p.actual;}
function overlapMinutes(a,b){let total=0;for(const aa of a)for(const bb of b){total+=Math.max(0,Math.min(aa[1],bb[1])-Math.max(aa[0],bb[0]));}return total;}
function reviews(){const sessions=sessionsSorted().filter(s=>state.filter==='all'||s.status===state.filter);return `${head('APPROVAL / LEDGER','Review & History','รายการรอตรวจสอบ ประวัติคาบเรียน การตัดชั่วโมง และการแก้ไขย้อนหลัง')}<div class="toolbar"><select class="pill-select" id="history-filter"><option value="all" ${state.filter==='all'?'selected':''}>ทั้งหมด</option><option value="pending" ${state.filter==='pending'?'selected':''}>Pending</option><option value="approved" ${state.filter==='approved'?'selected':''}>Approved</option><option value="cancelled" ${state.filter==='cancelled'?'selected':''}>Cancelled</option></select><span class="helper">เลือก Approve เพื่อหักชั่วโมงจากกระเป๋าคอร์สจริง</span></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>DATE / TIME</th><th>METHOD</th><th>STUDENTS</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${sessions.map(s=>`<tr><td>${esc(s.date)}<div class="td-secondary">${esc(s.start_time)}–${esc(s.end_time)}</div></td><td>${esc(s.mode)}<div class="td-secondary truncate">${esc(s.source_file||s.tutor)}</div></td><td>${all('Attendance').filter(a=>a.session_id===s.id).length}</td><td>${pill(s.status,s.status==='approved'?'green':s.status==='pending'?'gold':'red')}</td><td><div class="button-row">${btnInline('รายละเอียด','session-detail',s.id)} ${s.status==='pending'?btnInline('Approve','approve-session',s.id):''}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">ยังไม่มีประวัติคาบเรียน</td></tr>'}</tbody></table></div></div>`;}
function reports(){const approved=all('Sessions').filter(s=>s.status==='approved');const purchased=all('Ledger').filter(x=>x.type==='purchase').reduce((n,x)=>n+num(x.minutes),0);const deducted=all('Ledger').filter(x=>x.type==='deduct').reduce((n,x)=>n-num(x.minutes),0);const monthly=new Map();for(const s of approved){const month=(s.date||'').slice(0,7);monthly.set(month,(monthly.get(month)||0)+duration(s.start_time,s.end_time));}const bar=[...monthly].sort((a,b)=>a[0].localeCompare(b[0])).slice(-6),max=Math.max(1,...bar.map(x=>x[1]));return `${head('ANALYTICS / EXPORT','Reports & Summary','รายงานการสอน ชั่วโมงซื้อ และยอดคงเหลือ พร้อมส่งออกข้อมูล',`<div class="button-row">${btn('⇩ Export CSV','export-csv','soft')}${btn('Print / Save PDF','print-report','primary')}</div>`)}<div class="stats"><div class="stat"><div class="mini">Approved Sessions</div><div class="big">${approved.length}</div></div><div class="stat"><div class="mini">Package Hours Sold</div><div class="big">${fmt(purchased)}</div></div><div class="stat"><div class="mini">Hours Deducted</div><div class="big">${fmt(deducted)}</div></div><div class="stat"><div class="mini">Students</div><div class="big">${all('Students').length}</div></div></div><div class="two-col"><section class="panel"><h2 class="panel-title">Teaching Sessions by Month</h2><p class="panel-desc">นับระยะเวลาคาบเรียน ไม่ใช่ยอดการหักรวมทุกคน</p>${bar.map(([month,mins])=>`<div class="bar-row"><span>${esc(month)}</span><div class="bar-bg"><div class="bar-value" style="width:${Math.round(mins/max*100)}%"></div></div><strong>${fmt(mins)}</strong></div>`).join('')||'<div class="empty">ยังไม่มีข้อมูล</div>'}</section><section class="panel"><h2 class="panel-title">Student Balances</h2>${all('Students').map(s=>`<div class="list-row"><div><strong style="font-size:12px">${esc(s.name)}</strong><div class="td-secondary">${liveCourses(s.id).length} active courses</div></div><strong class="amount">${fmt(currentStudentTotal(s.id))}</strong></div>`).join('')}</section></div><div class="note">รายงาน PDF ใช้หน้าต่างพิมพ์ของเบราว์เซอร์ (เลือก Save as PDF) และ CSV เปิดใน Excel ได้ รองรับข้อมูลภาษาไทยด้วย UTF-8 BOM</div>`;}
function openConnection(){modal('Connection Settings',`<div class="form"><div class="note">${state.mode==='live'?'กำลังเชื่อม Google Sheets ส่วนตัว':'โหมดทดลองเก็บข้อมูลบนเบราว์เซอร์นี้เท่านั้น ไม่ใช่ฐานข้อมูลจริง'} · Google OAuth จะขอสิทธิ์อ่าน/แก้ไข Google Sheets จากบัญชีที่คุณเลือก</div><div class="kv"><span>Google Client ID</span><span>${config.googleClientId?esc(config.googleClientId.slice(0,24))+'…':'ยังไม่ตั้งค่าใน config.js'}</span><span>Spreadsheet ID</span><span>${config.spreadsheetId?esc(config.spreadsheetId.slice(0,25))+'…':'ยังไม่ตั้งค่าใน config.js'}</span></div><p class="subtle">1. รัน Setup.gs ในชีตส่วนตัว 2. ตั้งค่า OAuth Client ID ใน Google Cloud 3. กรอกค่าทั้งสองใน config.js 4. เปิดเว็บไซต์ GitHub Pages แล้วกด Connect</p><div class="button-row"><button class="btn primary" data-action="google-signin" ${!liveConfigured?'disabled':''}>Connect Google Sheets</button><button class="btn" data-action="demo-mode">Use Demo Mode</button>${state.mode==='live'?'<button class="btn danger" data-action="disconnect">Disconnect</button>':''}</div><p class="helper">เพื่อความปลอดภัยอย่าแชร์สิทธิ์แก้ไข Google Sheets กับผู้ใช้ที่ไม่ควรเข้าถึงนักเรียนทั้งหมด ฟีเจอร์สิทธิ์แยกรายติวเตอร์ต้องใช้ backend เพิ่มเติม</p></div>`);}
function googleLogin(){if(!liveConfigured)throw Error('กรุณากรอกค่า googleClientId และ spreadsheetId ใน config.js');if(!window.google?.accounts?.oauth2)throw Error('โหลด Google Sign-In ไม่สำเร็จ ตรวจสอบอินเทอร์เน็ต / การปิดกั้นสคริปต์');if(!state.tokenClient){state.tokenClient=google.accounts.oauth2.initTokenClient({client_id:config.googleClientId,scope:'https://www.googleapis.com/auth/spreadsheets',callback:async resp=>{if(resp.error)return notice(resp.error);try{state.token=resp.access_token;store=new SheetsStore(state.token);state.data=await store.load();state.mode='live';closeModal();render();toast('เชื่อม Google Sheets สำเร็จ');}catch(e){notice(e);}},error_callback:e=>notice(e?.message||'Google Sign-In error')});}state.tokenClient.requestAccessToken({prompt:'consent'});}
function disconnect(){const oldToken=state.token;state.token='';state.mode='demo';store=new DemoStore();if(window.google?.accounts?.oauth2&&oldToken)google.accounts.oauth2.revoke(oldToken,()=>{});closeModal();reload();}
function openStudentForm(existing){const s=existing||{};modal(existing?'แก้ไขนักเรียน':'เพิ่มนักเรียน',`<form id="student-form" class="form"><input type="hidden" name="id" value="${esc(s.id||'')}">${field('student-name','ชื่อ / ชื่อเล่นนักเรียน','text',s.name||'','required')}${field('student-email','อีเมล','email',s.email||'')}${field('student-aliases','ชื่อที่ใช้ใน Google Meet (คั่นด้วยเครื่องหมายจุลภาค)','text',s.aliases||'')}${selectField('student-status','สถานะ',`<option value="active" ${s.status!=='archived'?'selected':''}>Active</option><option value="archived" ${s.status==='archived'?'selected':''}>Archived</option>`)}<div class="field"><label>หมายเหตุ</label><textarea name="student-notes" rows="2">${esc(s.notes||'')}</textarea></div>${!existing?'<div class="note">หลังเพิ่มนักเรียน สามารถสร้างคอร์สและกำหนดชั่วโมงได้ทันที</div>':''}<button type="submit" class="btn primary">บันทึกนักเรียน</button></form>`);}
function openCourseForm(studentId=''){modal('สร้างคอร์สใหม่',`<form id="course-form" class="form">${selectField('course-student','นักเรียน',studentOptions(studentId),'required')}${field('course-title','ชื่อคอร์ส','text','Biology Olympiad','required')}<div class="grid-2">${field('course-date','วันเริ่มคอร์ส','date',dateNow(),'required')}${field('course-hours','จำนวนชั่วโมงที่ซื้อ','number','10','min="0.25" step="0.25" required')}</div><p class="helper">สร้างคอร์สใหม่แบบอิสระ หากต้องการต่อจากคอร์สเดิมให้กด “ต่อคอร์ส” ในโปรไฟล์นักเรียนเพื่อเก็บลำดับรอบ</p><button type="submit" class="btn primary">สร้างคอร์ส</button></form>`);}
function openRenew(c){if(!c)return;const b=balance(c.id);modal('ต่อคอร์ส · '+studentName(c.student_id),`<form id="renew-form" class="form"><input type="hidden" name="old_id" value="${esc(c.id)}"><div class="note">คอร์สเดิม <b>${esc(c.title)} · รอบ ${esc(c.cycle_no)}</b> คงเหลือ ${fmt(b)} ชั่วโมง<br>เมื่อยืนยันจะสร้างรอบใหม่และซ่อนรอบเดิมจากหน้าปัจจุบัน โดยยังเปิดดูประวัติย้อนหลังได้</div>${field('renew-title','ชื่อคอร์สรอบใหม่','text',c.title,'required')}<div class="grid-2">${field('renew-date','วันที่เริ่มเรียน','date',dateNow(),'required')}${field('renew-hours','ชั่วโมงที่ซื้อเพิ่ม','number','10','step="0.25" min="0" required')}</div>${selectField('renew-policy','จัดการชั่วโมงคงเหลือของรอบเก่า',`<option value="transfer">ยกยอด ${fmt(b)} ชั่วโมงไปคอร์สใหม่</option><option value="close">ปิดยอดเก่าและเริ่มรอบใหม่</option><option value="keep">เก็บยอดในคอร์สเดิมให้ใช้ได้ต่อ (Held)</option>`)}<button class="btn primary" type="submit">ยืนยันการต่อคอร์ส</button></form>`);}
function openTopup(c){if(!c)return;modal('เติมชั่วโมงคอร์สเดิม',`<form id="topup-form" class="form"><input type="hidden" name="course_id" value="${esc(c.id)}"><div class="note">${esc(studentName(c.student_id))} / ${esc(c.title)} · คงเหลือ ${fmt(balance(c.id))} ชั่วโมง</div>${field('topup-hours','ชั่วโมงที่เพิ่ม','number','5','min="0.25" step="0.25" required')}${field('topup-note','หมายเหตุ','text','ซื้อชั่วโมงเพิ่มเติม')}<button class="btn primary" type="submit">เพิ่มชั่วโมง</button></form>`);}
function openGroupForm(g){const m=(g?.member_ids||'').split('|');modal(g?'แก้ไขกลุ่มเรียน':'สร้างกลุ่มเรียน',`<form id="group-form" class="form"><input type="hidden" name="id" value="${esc(g?.id||'')}">${field('group-name','ชื่อกลุ่มเรียน','text',g?.name||'','required')}<div class="field"><label>เลือกสมาชิกในกลุ่ม</label>${all('Students').filter(s=>s.status==='active').map(s=>`<label class="check" style="display:flex;gap:9px;margin:8px 0"><input name="member" type="checkbox" value="${esc(s.id)}" ${m.includes(s.id)?'checked':''}>${esc(s.name)}</label>`).join('')}</div><button type="submit" class="btn primary">บันทึกกลุ่มเรียน</button></form>`);}
function courseHistory(courseId){const c=byId('Courses',courseId);if(!c)return;const ledger=all('Ledger').filter(l=>l.course_id===courseId).sort((a,b)=>b.created_at.localeCompare(a.created_at));const attends=all('Attendance').filter(a=>a.course_id===courseId);modal('ประวัติคอร์ส · '+c.title,`<div class="metric-strip"><div><small>นักเรียน</small><b>${esc(studentName(c.student_id))}</b></div><div><small>รอบ</small><b>${esc(c.cycle_no)}</b></div><div><small>คงเหลือ</small><b>${fmt(balance(c.id))}</b></div></div><h3 class="panel-title mt20">Hour Ledger (ประวัติการเปลี่ยนแปลง)</h3><div class="table-wrap mt12"><table><thead><tr><th>DATE</th><th>TYPE</th><th>CHANGE</th><th>NOTE</th></tr></thead><tbody>${ledger.map(l=>`<tr><td>${esc(l.created_at.slice(0,10))}</td><td>${esc(l.type)}</td><td class="${num(l.minutes)<0?'error-text':'success-text'}">${num(l.minutes)>0?'+':''}${fmt(Math.abs(num(l.minutes)))}</td><td>${esc(l.note||'')}</td></tr>`).join('')||'<tr><td colspan="4">ไม่มีรายการ</td></tr>'}</tbody></table></div><p class="helper mt12">รายการ Attendance ของคอร์สนี้ ${attends.length} รายการ สามารถดูรายละเอียดคาบเรียนในหน้า Review & History</p>`,`${btn('ปิด','close-modal')}`,true);}
function sessionDetail(id){const s=byId('Sessions',id);if(!s)return;const aa=all('Attendance').filter(a=>a.session_id===id);modal('Session Details',`<div class="kv"><span>วันที่เรียน</span><strong>${esc(s.date)}</strong><span>เวลา</span><strong>${esc(s.start_time)}–${esc(s.end_time)}</strong><span>แหล่งเวลา</span><strong>${esc(s.time_source)}</strong><span>ติวเตอร์</span><strong>${esc(s.tutor)}</strong><span>สถานะ</span><strong>${esc(s.status)}</strong><span>ไฟล์ต้นฉบับ</span><strong>${esc(s.source_file||'-')}</strong><span>หมายเหตุ</span><strong>${esc(s.notes||'-')}</strong></div><h3 class="panel-title mt20">Attendance & Deduction</h3><div class="table-wrap mt12"><table><thead><tr><th>STUDENT</th><th>COURSE</th><th>ACTUAL</th><th>DEDUCT</th><th>ACTION</th></tr></thead><tbody>${aa.map(a=>`<tr><td>${esc(studentName(a.student_id))}</td><td>${esc(courseTitle(a.course_id))}</td><td>${fmt(a.actual_minutes)}</td><td>${fmt(a.deduct_minutes)}</td><td>${s.status!=='cancelled'?btnInline('แก้ไข','edit-attendance',a.id):'-'}</td></tr>`).join('')}</tbody></table></div>`,`${s.status==='pending'?btnInline('Approve & Deduct','approve-session',s.id):''}${s.status!=='cancelled'?btnInline('ยกเลิกคาบ','cancel-session',s.id):''}<button class="btn" data-close>ปิด</button>`,true);}
function editAttendance(id){const a=byId('Attendance',id);if(!a)return;const s=byId('Sessions',a.session_id);if(!s||s.status==='cancelled')return;modal('แก้ไขการตัดชั่วโมง',`<form id="edit-att-form" class="form"><input type="hidden" name="id" value="${esc(id)}"><div class="note">${esc(studentName(a.student_id))} · ${esc(courseTitle(a.course_id))}<br>หากคาบนี้ได้รับอนุมัติแล้ว ระบบจะเพิ่มรายการปรับส่วนต่างลง Hour Ledger โดยไม่ลบรายการเดิม</div><div class="grid-2">${field('edit-join','เวลาเข้า','time',a.join_time)}${field('edit-leave','เวลาออก','time',a.leave_time)}</div>${field('edit-actual','เวลาที่เข้าร่วมจริง (นาที)','number',a.actual_minutes,'min="0" max="1440"')}${field('edit-minutes','เวลาที่ต้องตัด (นาที)','number',a.deduct_minutes,'min="0" max="1440" required')}${field('edit-reason','เหตุผลในการแก้ไข','text','','required')}<button class="btn primary" type="submit">บันทึกและปรับยอดชั่วโมง</button></form>`);}
async function onSubmit(e){const f=e.target;if(!['student-form','course-form','renew-form','topup-form','group-form','manual-form','edit-att-form','schedule-form','adjust-form'].includes(f.id))return;e.preventDefault();if(state.busy)return;try{if(f.id==='student-form')await saveStudent(f);if(f.id==='course-form')await saveCourse(f);if(f.id==='renew-form')await renewCourse(f);if(f.id==='topup-form')await topupCourse(f);if(f.id==='group-form')await saveGroup(f);if(f.id==='schedule-form')await saveSchedule(f);if(f.id==='adjust-form')await saveAdjustment(f);if(f.id==='manual-form')await saveManual(f);if(f.id==='edit-att-form')await saveEditAttendance(f);}catch(err){notice(err);}}
async function saveStudent(f){const id=inputVal(f,'id'),name=inputVal(f,'student-name');if(!name)throw Error('กรุณากรอกชื่อนักเรียน');const s={id:id||uuid(),name,email:inputVal(f,'student-email'),aliases:inputVal(f,'student-aliases'),status:inputVal(f,'student-status')||'active',created_at:byId('Students',id)?.created_at||now(),notes:inputVal(f,'student-notes')};await commit(id?{update:{Students:[s]},add:{Audit:[saveAudit('student_updated',s.id,{name})]}}:{add:{Students:[s],Audit:[saveAudit('student_created',s.id,{name})]}});state.studentId=s.id;state.view='students';closeModal();render();toast('บันทึกนักเรียนเรียบร้อย');}
async function saveCourse(f){const studentId=inputVal(f,'course-student'),title=inputVal(f,'course-title'),date=inputVal(f,'course-date'),mins=Math.round(Number(inputVal(f,'course-hours'))*60);if(!byId('Students',studentId)||!title||!dateValid(date)||!Number.isFinite(mins)||mins<=0)throw Error('กรอกข้อมูลคอร์สให้ครบและชั่วโมงต้องมากกว่า 0');const cycle=Math.max(0,...coursesOf(studentId).filter(c=>norm(c.title)===norm(title)).map(c=>num(c.cycle_no)))+1;const c={id:uuid(),student_id:studentId,title,cycle_no:cycle,start_date:date,purchased_minutes:mins,status:'active',previous_course_id:'',created_at:now(),closed_at:''};const l={id:uuid(),student_id:studentId,course_id:c.id,session_id:'',type:'purchase',minutes:mins,note:'สร้างคอร์สใหม่',created_at:now()};await commit({add:{Courses:[c],Ledger:[l],Audit:[saveAudit('course_created',c.id,{mins})]}});state.studentId=studentId;state.view='students';closeModal();render();toast('เพิ่มคอร์สแล้ว');}
async function renewCourse(f){const old=byId('Courses',inputVal(f,'old_id'));if(!old||old.status!=='active')throw Error('คอร์สเก่าไม่สามารถต่อได้');const date=inputVal(f,'renew-date'),title=inputVal(f,'renew-title'),mins=Math.round(Number(inputVal(f,'renew-hours'))*60),policy=inputVal(f,'renew-policy'),oldBalance=balance(old.id);if(!title||!dateValid(date)||!Number.isFinite(mins)||mins<0)throw Error('ข้อมูลคอร์สใหม่ไม่ถูกต้อง');if(mins===0&&oldBalance===0)throw Error('ไม่มีชั่วโมงใหม่หรือยอดยกมา');const cycle=Math.max(0,...coursesOf(old.student_id).filter(c=>norm(c.title)===norm(title)).map(c=>num(c.cycle_no)))+1;const newC={id:uuid(),student_id:old.student_id,title,cycle_no:cycle,start_date:date,purchased_minutes:mins,status:'active',previous_course_id:old.id,created_at:now(),closed_at:''};const updated={...old,status:policy==='keep'?'held':'archived',closed_at:now()};const ledger=[],t=now();if(mins>0)ledger.push({id:uuid(),student_id:old.student_id,course_id:newC.id,session_id:'',type:'purchase',minutes:mins,note:'ต่อคอร์สจากรอบ '+old.cycle_no,created_at:t});if(oldBalance>0&&policy!=='keep'){ledger.push({id:uuid(),student_id:old.student_id,course_id:old.id,session_id:'',type:policy==='transfer'?'transfer_out':'close_out',minutes:-oldBalance,note:policy==='transfer'?'ยกยอดไปคอร์สรอบ '+cycle:'ปิดยอดคอร์สเก่า',created_at:t});if(policy==='transfer')ledger.push({id:uuid(),student_id:old.student_id,course_id:newC.id,session_id:'',type:'transfer_in',minutes:oldBalance,note:'ยกยอดจากรอบ '+old.cycle_no,created_at:t});}await commit({update:{Courses:[updated]},add:{Courses:[newC],Ledger:ledger,Audit:[saveAudit('course_renewed',newC.id,{previous:old.id,policy,carried:oldBalance,newMinutes:mins})]}});state.studentId=old.student_id;state.view='students';closeModal();render();toast('ต่อคอร์สแล้ว ประวัติรอบเก่ายังอยู่');}
async function topupCourse(f){const c=byId('Courses',inputVal(f,'course_id')),mins=Math.round(Number(inputVal(f,'topup-hours'))*60);if(!c||!Number.isFinite(mins)||mins<=0)throw Error('ชั่วโมงที่เพิ่มไม่ถูกต้อง');await commit({update:{Courses:[{...c,purchased_minutes:num(c.purchased_minutes)+mins}]},add:{Ledger:[{id:uuid(),student_id:c.student_id,course_id:c.id,session_id:'',type:'purchase',minutes:mins,note:inputVal(f,'topup-note'),created_at:now()}],Audit:[saveAudit('course_topup',c.id,{mins})]}});closeModal();toast('เติมชั่วโมงเรียบร้อย');}
async function saveGroup(f){const id=inputVal(f,'id'),name=inputVal(f,'group-name'),members=[...f.querySelectorAll('input[name=member]:checked')].map(x=>x.value);if(!name)throw Error('กรุณากรอกชื่อกลุ่ม');const g={id:id||uuid(),name,member_ids:members.join('|'),created_at:byId('Groups',id)?.created_at||now()};await commit(id?{update:{Groups:[g]},add:{Audit:[saveAudit('group_updated',g.id,{members})]}}:{add:{Groups:[g],Audit:[saveAudit('group_created',g.id,{members})]}});closeModal();toast('บันทึกกลุ่มเรียนแล้ว');}
async function saveManual(f){const date=inputVal(f,'class_date'),start=inputVal(f,'class_start'),end=inputVal(f,'class_end'),dur=duration(start,end);if(!dateValid(date)||!Number.isFinite(dur)||dur<=0||dur>720)throw Error('วัน/เวลาไม่ถูกต้อง (หนึ่งคาบต้องไม่เกิน 12 ชั่วโมง)');const basis=inputVal(f,'deduction_mode');let mins=basis==='custom'?Number(inputVal(f,'class_custom')):dur;if(!Number.isFinite(mins)||mins<0||mins>720)throw Error('นาทีที่ตัดต้องอยู่ระหว่าง 0–720');mins=Math.round(mins);const students=[...f.querySelectorAll('input[name=participant]:checked')].map(x=>x.value);if(!students.length)throw Error('กรุณาเลือกนักเรียนอย่างน้อยหนึ่งคน');const courseIds=students.map(studentId=>{const select=f.querySelector(`select.manual-course[data-student="${CSS.escape(studentId)}"]`);const course=byId('Courses',select?.value);if(!course||course.student_id!==studentId||!['active','held'].includes(course.status))throw Error('กรุณาเลือกคอร์สที่ใช้งานได้ของ '+studentName(studentId));return course.id;});const t=now(),sid=uuid();const s={id:sid,date,start_time:start,end_time:end,mode:'manual',group_id:inputVal(f,'group_id'),tutor:inputVal(f,'tutor'),time_source:basis,status:'pending',source_file:'',notes:inputVal(f,'class_notes'),created_at:t};const aa=students.map((id,i)=>{const raw=f.querySelector(`input.manual-minute[data-student="${CSS.escape(id)}"]`)?.value;const custom=(raw===undefined||raw==='')?mins:Number(raw);if(!Number.isInteger(custom)||custom<0||custom>720)throw Error('นาทีที่กำหนดให้ '+studentName(id)+' ไม่ถูกต้อง');return {id:uuid(),session_id:sid,student_id:id,course_id:courseIds[i],join_time:start,leave_time:end,actual_minutes:dur,deduct_minutes:custom,status:'pending',source_name:'',created_at:t};});await commit({add:{Sessions:[s],Attendance:aa,Audit:[saveAudit('manual_session_created',sid,{count:aa.length})]}});state.view='reviews';toast('ลงเวลาแล้ว รอการอนุมัติตัดชั่วโมง');}
async function approveSession(id){const s=byId('Sessions',id);if(!s||s.status!=='pending')throw Error('คาบนี้ไม่ได้อยู่ในสถานะรออนุมัติ');const aa=all('Attendance').filter(a=>a.session_id===id);if(!aa.length)throw Error('ไม่มีนักเรียนในคาบนี้');const totals=new Map();for(const a of aa){if(!byId('Courses',a.course_id)||!['active','held'].includes(byId('Courses',a.course_id).status))throw Error('คอร์สไม่เปิดใช้งานแล้ว: '+studentName(a.student_id)+' — โปรดจัดการรายการ Pending ก่อนต่อคอร์ส');totals.set(a.course_id,(totals.get(a.course_id)||0)+num(a.deduct_minutes));}for(const [cid,used] of totals){if(balance(cid)<used)throw Error(`ชั่วโมงของ ${studentName(byId('Courses',cid).student_id)} ไม่พอ: ต้องใช้ ${fmt(used)} เหลือ ${fmt(balance(cid))} — เติมชั่วโมงหรือแก้ไขรายการก่อน`);}const t=now(),ledger=aa.filter(a=>num(a.deduct_minutes)>0).map(a=>({id:uuid(),student_id:a.student_id,course_id:a.course_id,session_id:id,type:'deduct',minutes:-num(a.deduct_minutes),note:'Approved session '+s.date,created_at:t}));await commit({update:{Sessions:[{...s,status:'approved'}],Attendance:aa.map(a=>({...a,status:'approved'}))},add:{Ledger:ledger,Audit:[saveAudit('session_approved',id,{attendees:aa.length})]}});closeModal();toast('อนุมัติและตัดชั่วโมงเรียบร้อย');}
async function cancelSession(id){const s=byId('Sessions',id);if(!s||s.status==='cancelled')throw Error('คาบนี้ถูกยกเลิกแล้ว');if(!confirm(`ยืนยันยกเลิกคาบ ${s.date}? ${s.status==='approved'?'ระบบจะคืนชั่วโมงให้ทุกคน':''}`))return;const aa=all('Attendance').filter(a=>a.session_id===id),t=now();const ledger=s.status==='approved'?aa.filter(a=>num(a.deduct_minutes)>0).map(a=>({id:uuid(),student_id:a.student_id,course_id:a.course_id,session_id:id,type:'refund',minutes:num(a.deduct_minutes),note:'Refund cancelled session',created_at:t})):[];await commit({update:{Sessions:[{...s,status:'cancelled'}],Attendance:aa.map(a=>({...a,status:'cancelled'}))},add:{Ledger:ledger,Audit:[saveAudit('session_cancelled',id,{refund:ledger.reduce((a,b)=>a+num(b.minutes),0)})]}});closeModal();toast('ยกเลิกคาบและปรับยอดแล้ว');}
async function saveEditAttendance(f){const a=byId('Attendance',inputVal(f,'id'));if(!a)throw Error('ไม่พบรายการ');const session=byId('Sessions',a.session_id);if(!session||session.status==='cancelled')throw Error('ไม่สามารถแก้ไขคาบที่ยกเลิก');const minutes=Number(inputVal(f,'edit-minutes')),actual=Number(inputVal(f,'edit-actual')),reason=inputVal(f,'edit-reason');if(!reason||!Number.isInteger(minutes)||minutes<0||minutes>720||!Number.isInteger(actual)||actual<0||actual>1440)throw Error('กรุณาระบุเหตุผลและนาทีที่ถูกต้อง');const delta=num(a.deduct_minutes)-minutes;if(session.status==='approved'&&delta<0&&balance(a.course_id)<-delta)throw Error('ชั่วโมงคงเหลือไม่พอสำหรับปรับเพิ่ม');const updated={...a,join_time:inputVal(f,'edit-join'),leave_time:inputVal(f,'edit-leave'),actual_minutes:actual,deduct_minutes:minutes};const ledger=delta&&session.status==='approved'?[{id:uuid(),student_id:a.student_id,course_id:a.course_id,session_id:a.session_id,type:'adjustment',minutes:delta,note:reason,created_at:now()}]:[];await commit({update:{Attendance:[updated]},add:{Ledger:ledger,Audit:[saveAudit('attendance_edited',a.id,{old:a.deduct_minutes,new:minutes,reason,actual})]}});closeModal();toast('แก้ไขและปรับยอดแล้ว');}
function parseTimeCell(value){let s=String(value??'').trim();const hh=s.match(/(?:^|\s)(\d{1,2}):(\d{2})(?::\d{2})?(?:\s*(AM|PM))?/i);if(hh){let h=+hh[1];if(hh[3]){if(h===12)h=0;if(hh[3].toUpperCase()==='PM')h+=12;}if(h<24&&+hh[2]<60)return String(h).padStart(2,'0')+':'+hh[2];}if(/^0\.\d+$/.test(s)){const mins=Math.round(Number(s)*1440);return `${String(Math.floor(mins/60)%24).padStart(2,'0')}:${String(mins%60).padStart(2,'0')}`;}return '';}
function mergeSegments(segments){const ordered=segments.filter(s=>Number.isFinite(s[0])&&Number.isFinite(s[1])&&s[1]>s[0]).sort((a,b)=>a[0]-b[0]);const merged=[];for(const [start,end] of ordered){const last=merged[merged.length-1];if(last&&start<=last[1])last[1]=Math.max(last[1],end);else merged.push([start,end]);}return merged;}
async function parseExcelFile(file){if(!window.XLSX)throw Error('ไม่สามารถโหลด XLSX parser ได้ โปรดเชื่อมต่ออินเทอร์เน็ตแล้วลองใหม่');const buffer=await file.arrayBuffer();let fingerprint='';if(crypto.subtle){const hashed=await crypto.subtle.digest('SHA-256',buffer);fingerprint=[...new Uint8Array(hashed)].map(n=>n.toString(16).padStart(2,'0')).join('');}else fingerprint=[...new Uint8Array(buffer)].reduce((h,b)=>((h*31)^b)>>>0,2166136261).toString(16)+'-'+file.size;const wb=XLSX.read(buffer,{type:'array',cellDates:false});const sheet=wb.Sheets[wb.SheetNames[0]];if(!sheet)throw Error('ไฟล์นี้ไม่พบชีตข้อมูล');const rows=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false});const headers=(rows[0]||[]).map(v=>norm(v));const column={first:headers.findIndex(v=>v==='ชื่อ'||v==='first name'),last:headers.findIndex(v=>v==='นามสกุล'||v==='last name'),email:headers.findIndex(v=>v==='อีเมล'||v==='email'),duration:headers.findIndex(v=>v==='ระยะเวลา'||v==='duration'),join:headers.findIndex(v=>v.includes('เวลาที่เข้าร่วม')||v.includes('join time')),leave:headers.findIndex(v=>v.includes('เวลาที่ออก')||v.includes('leave time'))};if(column.first<0||column.join<0||column.leave<0)throw Error('ไม่พบหัวคอลัมน์ ชื่อ / เวลาที่เข้าร่วม / เวลาที่ออก ใน '+file.name);const persons=new Map();for(const cells of rows.slice(1)){const name=[column.first>=0?cells[column.first]:'',column.last>=0?cells[column.last]:''].map(x=>String(x||'').trim()).filter(Boolean).join(' ');if(!name)continue;const email=String(cells[column.email]||'').trim();const join=parseTimeCell(cells[column.join]),leave=parseTimeCell(cells[column.leave]);const key=norm(name+'|'+email);if(!persons.has(key))persons.set(key,{name,email,segments:[],rawDuration:0});const p=persons.get(key);if(join&&leave){const a=minutesOf(join);let b=minutesOf(leave);if(b<a)b+=1440;if(b>a)p.segments.push([a,b]);}const d=String(cells[column.duration]||'');const m=d.match(/(?:(\d+)\s*ชม\.?\s*)?(?:(\d+)\s*นาที)?/);const minutes=m&&m[0]?num(m[1])*60+num(m[2]):0;p.rawDuration+=minutes;}
 const students=all('Students');const people=[...persons.values()].map(p=>{p.segments=mergeSegments(p.segments);p.actual=p.segments.length?p.segments.reduce((n,s)=>n+s[1]-s[0],0):p.rawDuration;p.join=p.segments.length?timeOfMin(p.segments[0][0]):'';p.leave=p.segments.length?timeOfMin(p.segments[p.segments.length-1][1]):'';const match=students.find(s=>[s.name,s.email,...String(s.aliases||'').split(',')].filter(Boolean).some(v=>norm(v)===norm(p.name)||norm(v)===norm(p.email)&&!!p.email));p.studentId=match?.id||'';p.courseId=match?liveCourses(match.id)[0]?.id||'':'';p.include=!!match;p.manualMinutes=null;return p;});if(!people.length)throw Error('ไม่พบข้อมูลผู้เข้าร่วมในไฟล์');const date=(file.name.match(/\b(20\d{2}-\d{2}-\d{2})\b/)||[])[1]||dateNow();const tutorIndex=Math.max(0,people.findIndex(p=>/suthawarin|tutor|teacher|ติวเตอร์|ครู/i.test(p.name)));people[tutorIndex].include=false;return {filename:file.name,fingerprint,date,people,tutorIndex,sourceIndex:tutorIndex,basis:'tutor',groupId:''};}
function timeOfMin(m){m=(m%1440+1440)%1440;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');}
async function loadCurrentImport(){if(state.importIndex>=state.importQueue.length){state.importDraft=null;state.importQueue=[];state.importIndex=0;render();return;}const file=state.importQueue[state.importIndex];const d=await parseExcelFile(file);state.importDraft=d;render();}
async function saveImport(){const d=state.importDraft;if(!d)throw Error('ยังไม่ได้เลือกไฟล์');if(all('Imports').some(x=>x.fingerprint===d.fingerprint))throw Error('ไฟล์นี้เคยนำเข้าแล้ว ระบบป้องกันการสร้างคาบซ้ำ');const date=$('#import-date')?.value;if(!dateValid(date))throw Error('วันที่ไม่ถูกต้อง');const tutor=d.people[d.tutorIndex],participants=d.people.filter((p,i)=>i!==d.tutorIndex&&p.include);if(!participants.length)throw Error('กรุณาติ๊กและจับคู่นักเรียนอย่างน้อยหนึ่งคน');for(const p of participants){if(!p.studentId||!p.courseId)throw Error('กรุณาจับคู่ชื่อและเลือกคอร์สสำหรับ '+p.name);const c=byId('Courses',p.courseId);if(!c||c.student_id!==p.studentId||!['active','held'].includes(c.status))throw Error('คอร์สของ '+p.name+' ไม่ถูกต้อง');const n=p.manualMinutes===null?calculatedImport(d,p):Number(p.manualMinutes);if(!Number.isFinite(n)||n<0||n>720)throw Error('ชั่วโมงที่จะตัดของ '+p.name+' ไม่ถูกต้อง');}const allStarts=d.people.flatMap(p=>p.segments.map(s=>s[0]));const allEnds=d.people.flatMap(p=>p.segments.map(s=>s[1]));const st=tutor?.join||(allStarts.length?timeOfMin(Math.min(...allStarts)):'00:00'),en=tutor?.leave||(allEnds.length?timeOfMin(Math.max(...allEnds)):'00:00');const t=now(),id=uuid();const s={id,date,start_time:st,end_time:en,mode:'excel',group_id:d.groupId||'',tutor:tutor?.name||'',time_source:d.basis,status:'pending',source_file:d.filename,notes:'Imported from Meet; review & approve before deduction',created_at:t};const attendance=participants.map(p=>({id:uuid(),session_id:id,student_id:p.studentId,course_id:p.courseId,join_time:p.join,leave_time:p.leave,actual_minutes:p.actual,deduct_minutes:p.manualMinutes===null?calculatedImport(d,p):num(p.manualMinutes),status:'pending',source_name:p.name,created_at:t}));const imp={id:uuid(),fingerprint:d.fingerprint,filename:d.filename,date,session_id:id,created_at:t};await commit({add:{Sessions:[s],Attendance:attendance,Imports:[imp],Audit:[saveAudit('excel_import',id,{filename:d.filename,people:attendance.length,basis:d.basis})]}});toast(`บันทึก ${attendance.length} รายการเป็น Pending แล้ว`);state.importIndex++;await loadCurrentImport();}
function downloadCSV(){const rows=[['วันที่','เวลาเริ่ม','เวลาสิ้นสุด','นักเรียน','คอร์ส','เข้าร่วมจริง (นาที)','ตัดชั่วโมง (นาที)','สถานะ','แหล่งข้อมูล']];for(const a of all('Attendance')){const s=byId('Sessions',a.session_id);rows.push([s?.date||'',s?.start_time||'',s?.end_time||'',studentName(a.student_id),courseTitle(a.course_id),num(a.actual_minutes),num(a.deduct_minutes),a.status,s?.source_file||'Manual']);}const csv='\ufeff'+rows.map(line=>line.map(cell=>{let v=String(cell??'');if(/^[=+@-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='AreWarin-TutorOS-Report-'+dateNow()+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function printReport(){const sessions=sessionsSorted(),html=`<!DOCTYPE html><html lang="th"><meta charset="utf-8"><title>AreWarin Tutor OS Report</title><style>body{font:12px Arial,sans-serif;padding:35px;color:#193f30}h1{font-size:24px}table{border-collapse:collapse;width:100%;font-size:11px}td,th{border:1px solid #ccd9ce;padding:8px;text-align:left}th{background:#eaf4eb}@media print{button{display:none}}</style><h1>AreWarin Tutor OS — Attendance Report</h1><p>Generated ${esc(dateNow())} · ${sessions.length} sessions</p><table><tr><th>วันที่</th><th>เวลา</th><th>นักเรียน</th><th>ชั่วโมงที่ตัด</th><th>สถานะ</th></tr>${sessions.flatMap(s=>all('Attendance').filter(a=>a.session_id===s.id).map(a=>`<tr><td>${esc(s.date)}</td><td>${esc(s.start_time)}–${esc(s.end_time)}</td><td>${esc(studentName(a.student_id))}</td><td>${fmt(a.deduct_minutes)}</td><td>${esc(s.status)}</td></tr>`)).join('')}</table><p><button onclick="window.print()">Print / Save PDF</button></p></html>`;const win=window.open('','_blank');if(!win)throw Error('กรุณาอนุญาต Pop-up เพื่อพิมพ์รายงาน');win.document.write(html);win.document.close();}
async function onClick(e){const nav=e.target.closest('[data-view]');if(nav){go(nav.dataset.view);return;}const close=e.target.closest('[data-close]');if(close){closeModal();return;}if(e.target.id==='overlay'){closeModal();return;}const el=e.target.closest('[data-action]');if(!el)return;const act=el.dataset.action,id=el.dataset.id;try{switch(act){case 'add-student':openStudentForm();break;case 'edit-student':openStudentForm(byId('Students',id));break;case 'add-course':openCourseForm();break;case 'new-course-for':openCourseForm(id);break;case 'student-detail':state.studentId=id;state.view='students';render();$('#profile')?.scrollIntoView({behavior:'smooth'});break;case 'hide-student':state.studentId='';render();break;case 'toggle-archive':state.showArchive=!state.showArchive;render();break;case 'renew-course':openRenew(byId('Courses',id));break;case 'renew-student':{const c=liveCourses(id)[0];if(!c)throw Error('ยังไม่มีคอร์สที่สามารถต่อได้');openRenew(c);break;}case 'topup-course':openTopup(byId('Courses',id));break;case 'adjust-course':openAdjustment(byId('Courses',id));break;case 'course-history':courseHistory(id);break;case 'add-group':openGroupForm();break;case 'add-schedule':openSchedule();break;case 'edit-schedule':openSchedule(byId('Schedules',id));break;case 'cancel-schedule':await cancelSchedule(id);break;case 'edit-group':openGroupForm(byId('Groups',id));break;case 'record-group':go('manual');setTimeout(()=>{const select=$('#group_id');if(select){select.value=id;select.dispatchEvent(new Event('change',{bubbles:true}));}},0);break;case 'go-manual':go('manual');break;case 'go-import':go('import');break;case 'go-reviews':go('reviews');break;case 'go-students':go('students');break;case 'connection':openConnection();break;case 'google-signin':googleLogin();break;case 'demo-mode':state.mode='demo';state.token='';store=new DemoStore();closeModal();await reload();break;case 'disconnect':disconnect();break;case 'approve-session':await approveSession(id);break;case 'cancel-session':await cancelSession(id);break;case 'edit-attendance':editAttendance(id);break;case 'session-detail':sessionDetail(id);break;case 'save-import':await saveImport();break;case 'skip-import':state.importIndex++;await loadCurrentImport();break;case 'close-modal':closeModal();break;case 'export-csv':downloadCSV();break;case 'print-report':printReport();break;}}catch(err){notice(err);}}
async function onChange(e){const t=e.target;try{if(t.id==='excel-file'){const files=[...t.files];if(!files.length)return;state.importQueue=files;state.importIndex=0;await loadCurrentImport();toast('อ่านรายงาน Excel สำเร็จ');return;}if(t.id==='group_id'){const g=byId('Groups',t.value),ids=(g?.member_ids||'').split('|');document.querySelectorAll('.manual-check').forEach(check=>check.checked=ids.includes(check.value));return;}if(t.id==='history-filter'){state.filter=t.value;render();return;}const d=state.importDraft;if(!d)return;if(t.id==='import-date'){d.date=t.value;return;}if(t.id==='import-group'){d.groupId=t.value;return;}if(t.id==='import-tutor'){d.tutorIndex=Number(t.value);d.people[d.tutorIndex].include=false;d.people.forEach(p=>p.manualMinutes=null);render();return;}if(t.id==='import-basis'){d.basis=t.value;d.people.forEach(p=>p.manualMinutes=null);render();return;}if(t.id==='import-source'){d.sourceIndex=Number(t.value);d.people.forEach(p=>p.manualMinutes=null);render();return;}let i;if(t.hasAttribute('data-import-include')){i=Number(t.dataset.importInclude);d.people[i].include=t.checked;return;}if(t.hasAttribute('data-import-student')){i=Number(t.dataset.importStudent);const p=d.people[i];p.studentId=t.value;p.courseId=liveCourses(p.studentId)[0]?.id||'';render();return;}if(t.hasAttribute('data-import-course')){i=Number(t.dataset.importCourse);d.people[i].courseId=t.value;return;}if(t.hasAttribute('data-import-minutes')){i=Number(t.dataset.importMinutes);d.people[i].manualMinutes=t.value===''?NaN:Number(t.value);return;}}catch(err){notice(err);}}
function onInput(e){if(e.target.id==='student-search'){state.search=e.target.value;const pos=e.target.selectionStart;render();const next=$('#student-search');next?.focus();try{next.setSelectionRange(pos,pos);}catch{}}if(e.target.hasAttribute('data-import-minutes')){const d=state.importDraft;if(d)d.people[Number(e.target.dataset.importMinutes)].manualMinutes=e.target.value===''?NaN:Number(e.target.value);}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
function scheduledDates(){const result=[],start=dateNow();for(const entry of all('Schedules').filter(e=>e.status==='active')){for(let i=0;i<21;i++){const d=new Date(start+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);const ds=d.toISOString().slice(0,10);if(ds<entry.date)continue;if(entry.repeat_rule==='weekly'){if(new Date(ds+'T12:00:00Z').getUTCDay()!==new Date(entry.date+'T12:00:00Z').getUTCDay())continue;}else if(ds!==entry.date)continue;result.push({...entry,on_date:ds});}}return result.sort((a,b)=>(a.on_date+a.start_time).localeCompare(b.on_date+b.start_time));}
function schedule(){const items=scheduledDates();return `${head('CALENDAR / PLANNING','Class Schedule','สร้างตารางเรียนประจำและนัดหมาย ช่วยดูคาบเรียนล่วงหน้า',btn('＋ เพิ่มตารางเรียน','add-schedule','primary'))}<div class="panel"><div class="note">ตารางเรียนเป็นรายการวางแผน ยังไม่ตัดชั่วโมงโดยอัตโนมัติ เมื่อต้องการตัดชั่วโมงให้ไปที่ Record Hours หรือ Import Excel แล้วอนุมัติ</div><div class="table-wrap mt20"><table><thead><tr><th>DATE</th><th>TIME</th><th>STUDENT / GROUP</th><th>TUTOR</th><th>REPEAT</th><th>ACTION</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.on_date)}</td><td>${esc(x.start_time)}–${esc(x.end_time)}</td><td>${esc(x.group_id?byId('Groups',x.group_id)?.name||'-':studentName(x.student_id))}</td><td>${esc(x.tutor)}</td><td>${pill(x.repeat_rule)}</td><td>${btnInline('แก้ไข','edit-schedule',x.id)} ${btnInline('ยกเลิก','cancel-schedule',x.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีตารางเรียนที่กำลังจะมาถึง</td></tr>'}</tbody></table></div></div>`;}
function openSchedule(s){modal(s?'แก้ไขตารางเรียน':'เพิ่มตารางเรียน',`<form class="form" id="schedule-form"><input type="hidden" name="id" value="${esc(s?.id||'')}">${field('sched-date','วันที่เริ่ม','date',s?.date||dateNow(),'required')}<div class="grid-2">${field('sched-start','เวลาเริ่ม','time',s?.start_time||'18:00','required')}${field('sched-end','เวลาสิ้นสุด','time',s?.end_time||'20:00','required')}</div>${selectField('sched-student','นักเรียนรายบุคคล',studentOptions(s?.student_id||''))}${selectField('sched-group','หรือเลือกกลุ่มเรียน',`<option value="">— ไม่ใช่กลุ่ม —</option>${all('Groups').map(g=>`<option value="${esc(g.id)}" ${s?.group_id===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}`)}<div class="grid-2">${field('sched-tutor','ติวเตอร์','text',s?.tutor||'Suthawarin','required')}${selectField('sched-repeat','ทำซ้ำ',`<option value="once" ${s?.repeat_rule!=='weekly'?'selected':''}>เฉพาะครั้งนี้</option><option value="weekly" ${s?.repeat_rule==='weekly'?'selected':''}>ทุกสัปดาห์</option>`)}</div>${field('sched-note','หมายเหตุ','text',s?.notes||'')}<button class="btn primary" type="submit">บันทึกตารางเรียน</button></form>`);}
async function saveSchedule(f){const id=inputVal(f,'id'),date=inputVal(f,'sched-date'),start=inputVal(f,'sched-start'),end=inputVal(f,'sched-end'),studentId=inputVal(f,'sched-student'),groupId=inputVal(f,'sched-group');if(!dateValid(date)||!Number.isFinite(duration(start,end))||duration(start,end)<=0||duration(start,end)>720||(!studentId&&!groupId))throw Error('กรุณาระบุวันที่ เวลา และนักเรียนหรือกลุ่มที่ต้องการสอน');const item={id:id||uuid(),date,student_id:groupId?'':studentId,group_id:groupId,start_time:start,end_time:end,tutor:inputVal(f,'sched-tutor'),repeat_rule:inputVal(f,'sched-repeat'),status:'active',notes:inputVal(f,'sched-note'),created_at:byId('Schedules',id)?.created_at||now()};const change=id?{update:{Schedules:[item]},add:{Audit:[saveAudit('schedule_updated',item.id,{date})]}}:{add:{Schedules:[item],Audit:[saveAudit('schedule_created',item.id,{date})]}};await commit(change);closeModal();toast('บันทึกตารางเรียนแล้ว');}
async function cancelSchedule(id){const s=byId('Schedules',id);if(!s)return;if(!confirm('ยกเลิกตารางเรียนนี้ (รวมรายการทำซ้ำถ้ามี) ใช่หรือไม่?'))return;await commit({update:{Schedules:[{...s,status:'cancelled'}]},add:{Audit:[saveAudit('schedule_cancelled',id,{date:s.date})]}});toast('ยกเลิกตารางเรียนแล้ว');}
function openAdjustment(c){if(!c||!['active','held'].includes(c.status))return;modal('ปรับยอดชั่วโมงคอร์ส',`<form class="form" id="adjust-form"><input type="hidden" name="course_id" value="${esc(c.id)}"><div class="note">${esc(studentName(c.student_id))} · ${esc(c.title)} · คงเหลือ ${fmt(balance(c.id))} ชั่วโมง<br>ใช้ตัวเลขบวกเพื่อเพิ่มชั่วโมง หรือใส่ค่าติดลบเพื่อลดชั่วโมง โดยต้องระบุเหตุผลเพื่อเก็บประวัติ</div>${field('adjust-minutes','นาทีที่ต้องการปรับ (เช่น +30 หรือ -15)','number','30','step="1" min="-10000" max="10000" required')}${field('adjust-reason','เหตุผลในการปรับยอด','text','','required')}<button class="btn primary" type="submit">บันทึกรายการปรับยอด</button></form>`);}
async function saveAdjustment(f){const c=byId('Courses',inputVal(f,'course_id')),minutes=Number(inputVal(f,'adjust-minutes')),reason=inputVal(f,'adjust-reason');if(!c||!['active','held'].includes(c.status)||!Number.isInteger(minutes)||minutes===0||Math.abs(minutes)>10000||!reason)throw Error('รายการปรับยอดไม่ถูกต้อง');if(balance(c.id)+minutes<0)throw Error('ไม่สามารถปรับยอดให้ติดลบ');await commit({add:{Ledger:[{id:uuid(),student_id:c.student_id,course_id:c.id,session_id:'',type:'adjustment',minutes,note:reason,created_at:now()}],Audit:[saveAudit('manual_adjustment',c.id,{minutes,reason})]}});closeModal();toast('ปรับยอดเรียบร้อยพร้อมบันทึกประวัติ');}
